window.SCHOOL_LISTENING={"../assets/media/fe74950e306c8aee4fc4cdf2292bbfb13475c3405bcbcb4c61cdbbb4357f690d.mp3":[{"id":"PPT_fe74950e306c8aee","audioId":"PPT_fe74950e306c8aee","title":"Book 2 · Unit 4 · RW · READING 2","subtitle":"READING 2 · source slide 105","duration":208.77,"cues":[{"start":0,"end":6.36,"text":"Surviving the Sea of Sand How to stay alive in the Sahara Desert,","coverage":1},{"start":6.74,"end":13.32,"text":"Yuen Bar Can you imagine a sea of sand three times bigger than India?","coverage":1},{"start":14.36,"end":16.28,"text":"This is the Sahara Desert,","coverage":1},{"start":16.7,"end":19.4,"text":"the largest hot desert in the world.","coverage":1},{"start":20.04,"end":26.38,"text":"It covers 11 countries in North Africa and is over nine million square kilometers.","coverage":1},{"start":26.38,"end":30.28,"text":"That's more than 25 % of Africa.","coverage":1},{"start":31.3,"end":32.4,"text":"In the Sahara,","coverage":1},{"start":32.86,"end":36.02,"text":"temperatures are very different during the day and at night.","coverage":1},{"start":36.62,"end":39.72,"text":"It is much hotter during the day than at night.","coverage":1},{"start":40.46,"end":41.32,"text":"During the day,","coverage":1},{"start":41.74,"end":44.1,"text":"the hottest time is between two p .m.","coverage":1},{"start":44.22,"end":45.42,"text":"and four p .m.","coverage":1},{"start":45.44,"end":48.54,"text":"when temperatures rise to 33 degrees centigrade.","coverage":1},{"start":49.24,"end":51.64,"text":"But it is very cold at night.","coverage":1},{"start":51.64,"end":54.74,"text":"The coldest time is at four a .m.","coverage":1},{"start":55,"end":58.38,"text":"when temperatures fall to minus one degree centigrade.","coverage":1},{"start":59.66,"end":61.86,"text":"Though not the driest place in the world,","coverage":1},{"start":62.28,"end":64.3,"text":"the Sahara is very dry.","coverage":1},{"start":65.02,"end":69.06,"text":"The average precipitation in a year is only 70 millimeters.","coverage":1},{"start":70.46,"end":73.54,"text":"Because of the extreme temperatures in the desert,","coverage":1},{"start":74.14,"end":77,"text":"it is a very difficult place to survive.","coverage":1},{"start":78.08,"end":79.18,"text":"Marco Rivera,","coverage":1},{"start":79.56,"end":80.68,"text":"our survival expert,","coverage":1},{"start":81,"end":81.88,"text":"has some tips.","coverage":1},{"start":83.2,"end":85.3,"text":"Take warm clothes and a blanket.","coverage":1},{"start":86.08,"end":87.16,"text":"You will need a hat,","coverage":1},{"start":87.64,"end":88.42,"text":"long trousers,","coverage":1},{"start":88.82,"end":91.28,"text":"and a woolen jumper to keep you warm at night.","coverage":1},{"start":92.04,"end":95.66,"text":"During the day, cover your body, head, and face.","coverage":1},{"start":96.32,"end":100.28,"text":"Clothes protect you from the sun and keep water in your body.","coverage":1},{"start":100.98,"end":103.6,"text":"You will also need a warm blanket at night.","coverage":1},{"start":104.02,"end":106.18,"text":"It can get cold very quickly.","coverage":1},{"start":106.18,"end":108.2,"text":"When the temperature drops,","coverage":1},{"start":108.7,"end":111.78,"text":"it can be a shock and make you feel even colder.","coverage":1},{"start":113.38,"end":117.3,"text":"A car is easier to see than a person walking in the desert.","coverage":1},{"start":118.06,"end":123.26,"text":"You can also use the mirrors from your car to signal to planes and other cars.","coverage":1},{"start":124.18,"end":126.44,"text":"You can use your car tires to make a fire.","coverage":1},{"start":127,"end":128.76,"text":"A fire is easy to see.","coverage":1},{"start":129.36,"end":132.82,"text":"It will help people find you and it will keep you warm at night.","coverage":1},{"start":133.58,"end":137.08,"text":"Try to drink some water at least once every hour.","coverage":1},{"start":137.82,"end":141.24,"text":"You need your water to last as long as possible.","coverage":1},{"start":141.92,"end":143.72,"text":"Drink only what you need.","coverage":1},{"start":144.48,"end":147.66,"text":"When you talk, you lose water from your body.","coverage":1},{"start":148.42,"end":150.96,"text":"Keep your mouth closed and do not talk.","coverage":1},{"start":152.28,"end":156.86,"text":"If you eat, you will get thirsty and drink all of your water more quickly.","coverage":1},{"start":157.48,"end":162.2,"text":"You can eat a little but only to stop you from feeling very hungry.","coverage":1},{"start":162.82,"end":167.32,"text":"Eat very small amounts of food and eat very slowly.","coverage":1},{"start":168.3,"end":170.16,"text":"You can live for three weeks with","coverage":1},{"start":170.16,"end":170.46,"text":"no","coverage":1},{"start":170.46,"end":170.9,"text":"food,","coverage":1},{"start":171.42,"end":174.68,"text":"but you can only live for three days without water.","coverage":1},{"start":175.92,"end":179.78,"text":"It is very important to stay out of the sun during the day.","coverage":1},{"start":180.46,"end":183.48,"text":"Make a hole under your car and lie there.","coverage":1},{"start":184.16,"end":186.76,"text":"This will keep you cool and help you sleep.","coverage":1},{"start":187.84,"end":189.98,"text":"Find a warm place to sleep at night.","coverage":1},{"start":189.98,"end":193.8,"text":"A spot near a tree or a rock will be the warmest.","coverage":1},{"start":194.36,"end":196.94,"text":"But be careful before you decide where to sleep.","coverage":1},{"start":197.86,"end":202.82,"text":"Dangerous animals like snakes and scorpions also like to sleep in these places.","coverage":1},{"start":203.54,"end":206.92,"text":"Look carefully for animals before you lie down.","coverage":1}],"file":"6867df33a219fce03b80.js","track":0,"media":"../assets/media/fe74950e306c8aee4fc4cdf2292bbfb13475c3405bcbcb4c61cdbbb4357f690d.mp3"}],"../assets/media/e0392ecab36b7ddca04789419fd861926ddab03b5ed124fe6c89c4fb4098516a.mp3":[{"id":"PPT_e0392ecab36b7ddc","audioId":"PPT_e0392ecab36b7ddc","title":"Book 2 · Unit 4 · RW · READING 1","subtitle":"READING 1 · source slide 68","duration":243.96,"cues":[{"start":0,"end":12.92,"text":"Living in the Wettest Place on Earth Every year, the people living in the state of Meghalaya in northeast India spend many months preparing for heavy rain.","coverage":1},{"start":13.52,"end":16.1,"text":"The rains, called the summer monsoon,","coverage":1},{"start":16.42,"end":19.9,"text":"can last for days or weeks without stopping.","coverage":1},{"start":20.72,"end":30.08,"text":"The Guinness Book of World Records says that Meghalaya, which means abode of clouds, is one of the wettest places on Earth.","coverage":1},{"start":30.58,"end":33.92,"text":"It gets almost 12 ,000 millimeters,","coverage":1},{"start":34.36,"end":38.76,"text":"about 470 inches of rain each year.","coverage":1},{"start":39.7,"end":41.9,"text":"Compare this to the Sahara Desert,","coverage":1},{"start":42.26,"end":51.04,"text":"the world's largest hot desert, which gets between 100 and 250 millimeters, four to ten inches.","coverage":1},{"start":52.1,"end":56.3,"text":"Summer monsoons usually last from April until October.","coverage":1},{"start":56.84,"end":61.22,"text":"They can change the lives of a fifth of the world's population.","coverage":1},{"start":62.34,"end":70.32,"text":"Some people in the town of Masinram in Meghalaya prepare for the rain by covering their homes with dried grass.","coverage":1},{"start":71.2,"end":75.46,"text":"They do this so that the noise from the rain falling on their roof,","coverage":1},{"start":75.9,"end":78.54,"text":"windows, and walls is not as loud.","coverage":1},{"start":79.52,"end":82.22,"text":"Although rain may not get into the home,","coverage":1},{"start":82.62,"end":89.68,"text":"the walls inside can feel a bit wet because the fog from outside comes into the house.","coverage":1},{"start":90.34,"end":98.9,"text":"Sometimes the rain is so loud that the schools have to close because the children cannot hear what the teacher says in the lesson.","coverage":1},{"start":100.36,"end":103.64,"text":"The monsoon storms can leave people in the dark.","coverage":1},{"start":104.08,"end":109.08,"text":"Thunder and lightning can damage electricity cables and stop the power supply.","coverage":1},{"start":110.16,"end":114.6,"text":"Homes and businesses can be without electricity for many days.","coverage":1},{"start":114.6,"end":117.44,"text":"If people do not have electricity,","coverage":1},{"start":117.84,"end":121.12,"text":"they cannot turn on their lights or cook their food.","coverage":1},{"start":121.7,"end":129.3,"text":"It also means it is very dark inside because even during the day the sun is behind the clouds.","coverage":1},{"start":130.18,"end":132.32,"text":"In addition, because there is often","coverage":1},{"start":132.32,"end":132.7,"text":"no","coverage":1},{"start":132.7,"end":133.96,"text":"sun for weeks,","coverage":1},{"start":134.36,"end":139.4,"text":"clothes do not dry very well and can have a strange, bad smell.","coverage":1},{"start":140.54,"end":143.9,"text":"Heavy monsoon rains can cause landslides.","coverage":1},{"start":143.9,"end":150.88,"text":"Landslides are dangerous because they can badly damage buildings or even whole villages.","coverage":1},{"start":151.64,"end":155.46,"text":"They can also damage roads and stop access to water.","coverage":1},{"start":156.32,"end":160.38,"text":"This means there is not enough clean water for people to drink.","coverage":1},{"start":161.18,"end":165.52,"text":"In 2021, there was a landslide in Mumbai, India.","coverage":1},{"start":166.02,"end":170.68,"text":"It fell on people's homes as they were sleeping and several people died.","coverage":1},{"start":171.68,"end":175.64,"text":"People can spend a lot of time indoors during the monsoon,","coverage":1},{"start":176,"end":177.72,"text":"but life does not stop.","coverage":1},{"start":178.32,"end":180.94,"text":"They still go to work and shops open.","coverage":1},{"start":181.78,"end":182.84,"text":"In Mausinram,","coverage":1},{"start":183.28,"end":187.9,"text":"people make things called nups using bamboo and grass.","coverage":1},{"start":188.8,"end":194.54,"text":"Nups are like umbrellas, but they are a bit bigger and shaped like a tortoise.","coverage":1},{"start":194.74,"end":197.46,"text":"One nup takes about an hour to make.","coverage":1},{"start":197.46,"end":202.22,"text":"A nup can keep someone dry from their head to their knees.","coverage":1},{"start":202.94,"end":207.98,"text":"Some people who work in their homes use the monsoon as a business opportunity.","coverage":1},{"start":208.76,"end":214.78,"text":"For example, they make nups for the six -month monsoon season and sell them to visitors.","coverage":1},{"start":216.22,"end":221.18,"text":"Summer monsoons are not a new phenomenon, but experts are worried.","coverage":1},{"start":221.18,"end":226.54,"text":"Research suggests that climate change caused by human activity,","coverage":1},{"start":227.06,"end":229.34,"text":"such as industry and agriculture,","coverage":1},{"start":229.7,"end":230.8,"text":"will make a difference.","coverage":1},{"start":231.52,"end":233.3,"text":"In India, for example,","coverage":1},{"start":233.7,"end":242.06,"text":"the monsoon season is likely to get wetter and more dangerous because extreme rainfall events will happen more often.","coverage":1}],"file":"96e4e3e555ccc83f346b.js","track":0,"media":"../assets/media/e0392ecab36b7ddca04789419fd861926ddab03b5ed124fe6c89c4fb4098516a.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1. A tornado is a dangerous example of which type of weather? a rain b wind c snow. Answer: b. wind.","slide":4,"shape":"16","bookPage":"82"},{"text":"2. Where are tornadoes common? Possible answer: Parts of America.","slide":4,"shape":"18","bookPage":"82"},{"text":"3. Have you ever watched a thunderstorm? Possible answer: Yes, I have. I saw one last week.","slide":4,"shape":"6","bookPage":"82"},{"text":"4. Why are some people scared of storms? Possible answer: Storms can damage buildings.","slide":5,"shape":"11","bookPage":"82"},{"text":"1 Information about different weather. Included.","slide":13,"shape":"19","bookPage":"82"},{"text":"2 The weather in one country. Not included.","slide":13,"shape":"20","bookPage":"82"},{"text":"3 How people prepare for snowstorms. Not included.","slide":13,"shape":"21","bookPage":"82"},{"text":"4 How rainbows happen. Included.","slide":13,"shape":"22","bookPage":"82"},{"text":"5 The reasons why some places have certain weather. Included.","slide":13,"shape":"23","bookPage":"82"},{"text":"6 The best place to see a beautiful sunset. Not included.","slide":13,"shape":"24","bookPage":"82"},{"text":"1. Sun haloes are more common in cold places.","slide":16,"shape":"15","bookPage":"83"},{"text":"2. Supercell storms happen all over the world.","slide":16,"shape":"17","bookPage":"83"},{"text":"3. About 30% of supercell storms become tornadoes.","slide":16,"shape":"6","bookPage":"83"},{"text":"4. Waterspouts can be more than 1,500 metres tall.","slide":16,"shape":"8","bookPage":"83"},{"text":"5. Most waterspouts die in about five minutes.","slide":17,"shape":"13","bookPage":"83"},{"text":"1 How do supercell storms form? Warm, wet air rises. Winds push and pull the air, and it begins to rotate.","slide":20,"shape":"13","bookPage":"83"},{"text":"2 What is a lenticular cloud? It is a cloud like a cap. It forms when winds push wet air over high mountains and the air cools.","slide":20,"shape":"15","bookPage":"83"},{"text":"5 The speaker says that waterspouts can be dangerous to ships, planes and swimmers. Why is this? Their height and strong winds could damage a ship or a low-flying plane, and put swimmers at risk of drowning.","slide":22,"shape":"11","bookPage":"83"},{"text":"1 Have you seen any of the strange weather in the video? If yes, describe what you saw. If not, say what strange weather you would most like to see. I have not seen these types of weather. I would like to see a sun halo because it looks beautiful.","slide":24,"shape":"13","bookPage":"83"},{"text":"2 Do you think we will see more and more strange weather in the future? Why / Why not? I think we may see more extreme storms because of climate change.","slide":24,"shape":"15","bookPage":"83"},{"text":"1 almost (adv) nearly but not exactly","slide":33,"shape":"6","bookPage":"84"},{"text":"2 cover (v) to lie on the surface of something","slide":33,"shape":"7","bookPage":"84"},{"text":"3 dangerous (adj) able to harm or hurt somebody or something","slide":33,"shape":"8","bookPage":"84"},{"text":"4 lasted (v) continued for a period of time","slide":33,"shape":"9","bookPage":"84"},{"text":"5 lightning (n) a flash of bright light in the sky during a storm","slide":33,"shape":"10","bookPage":"84"},{"text":"6 thunder (n) the sudden loud noise that comes after a flash of bright light in the sky\nduring a storm","slide":33,"shape":"11","bookPage":"84"},{"text":"7 huge (adj) very big","slide":33,"shape":"12","bookPage":"84"},{"text":"1 Have you ever watched a huge thunder and lightning storm that lasted for several\nhours? If not, would you like to?","slide":39,"shape":"6","bookPage":"84"},{"text":"2 In your country, does snow ever cover the ground? If not, would you like to see that?","slide":39,"shape":"7","bookPage":"84"},{"text":"3 In your country, can people drive on the roads after a storm or is it too dangerous? Give\nreasons.","slide":39,"shape":"8","bookPage":"84"},{"text":"1 Have you ever watched a huge thunder and lightning storm that lasted for several hours? If not, would you like to? Possible answer: I have watched a long thunder and lightning storm. I stayed inside and watched from a safe place.","slide":40,"shape":"10","bookPage":"84"},{"text":"2 In your country, does snow ever cover the ground? If not, would you like to see that? Possible answer: Snow sometimes covers the ground where I live. I enjoy how it changes the view.","slide":40,"shape":"11","bookPage":"84"},{"text":"3 In your country, can people drive on the roads after a storm or is it too dangerous? Give reasons. Possible answer: Some roads can be too dangerous after a storm because floodwater can hide damage.","slide":40,"shape":"12","bookPage":"84"},{"text":"1 What kind of weather do you usually have where you live? It is very dry where I live. We have lots of sun, and the temperature is sometimes about 40 degrees.","slide":42,"shape":"16","bookPage":"84"},{"text":"2 Does the weather in your country change throughout the year? If so, how? Yes. We have spring, summer, autumn and winter. In winter, it snows.","slide":42,"shape":"18","bookPage":"84"},{"text":"3 Do you prefer the weather in summer or winter? Why? I prefer summer because I can go to the beach with my friends.","slide":43,"shape":"17","bookPage":"84"},{"text":"Paragraph 2: Some people in the town of Mawsynram, in Meghalaya, prepare for the rain by covering their homes with dried grass. They do this so that the noise from the rain falling on their roof, windows and walls is not as loud. Although rain may not get into the home, the walls inside can feel a bit wet because the fog from outside comes into the house. Sometimes, the rain is so loud that the schools have to close because the children cannot hear what the teacher says in the lesson.","slide":63,"shape":"16","bookPage":"86"},{"text":"Paragraph 3: The monsoon storms can leave people in the dark. Thunder and lightning can damage electricity cables and stop the power supply. Homes and businesses can be without electricity for many days. If people do not have electricity, they cannot turn on their lights or cook their food. It also means it is very dark inside because, even during the day, the sun is behind the clouds. In addition, because there is often no sun for weeks, clothes do not dry very well and can have a strange, bad smell.","slide":64,"shape":"13","bookPage":"86"},{"text":"Paragraph 4: Heavy monsoon rains can cause landslides. Landslides² are dangerous because they can badly damage buildings or even whole villages. They can also damage roads and stop access to water. This means there is not enough clean water for people to drink. In 2021, there was a landslide in Mumbai, India. It fell on people’s homes as they were sleeping, and several people died.","slide":65,"shape":"13","bookPage":"86"},{"text":"Paragraph 5: People can spend a lot of time indoors during the monsoon, but life does not stop. They still go to work and shops open. In Mawsynram, people make things called knups, using bamboo and grass. Knups are like umbrellas, but they are a bit bigger and shaped like a tortoise. One knup takes about an hour to make. A knup can keep somebody dry from their head to their knees. Some people who work in their homes use the monsoon as a business opportunity. For example, they make knups for the six-month monsoon season and sell them to visitors.","slide":66,"shape":"13","bookPage":"86"},{"text":"Paragraph 6: Summer monsoons are not a new phenomenon, but experts are worried. Research suggests that climate change caused by human activity, such as industry and agriculture, will make a difference. In India, for example, the monsoon season is likely to get wetter and more dangerous because extreme³ rainfall events will happen more often.","slide":67,"shape":"13","bookPage":"86"},{"text":"1 Every year almost 12,000 millimetres of rain fall … a in Meghalaya. b in the Sahara. Answer: a in Meghalaya.","slide":77,"shape":"15","bookPage":"86"},{"text":"2 People cover their homes with grass … a to keep their homes dry. b to keep their homes quiet. Answer: b to keep their homes quiet.","slide":77,"shape":"17","bookPage":"86"},{"text":"3 Landslides can … a damage villages. b provide drinking water. Answer: a damage villages.","slide":77,"shape":"6","bookPage":"86"},{"text":"4 Climate change … a will not affect monsoon weather. b may affect monsoon weather. Answer: b may affect monsoon weather.","slide":78,"shape":"10","bookPage":"86"},{"text":"1 This text is an excerpt from a a newspaper. b a textbook. Answer: b a textbook.","slide":87,"shape":"12","bookPage":"86"},{"text":"2 What kind of information is included in the text? a facts b opinions Answer: a facts","slide":87,"shape":"14","bookPage":"86"},{"text":"1. Summary gap 1\nAnswer: eight","slide":90,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nAnswer: iii","slide":90,"shape":"8","bookPage":null},{"text":"a careful (adj) paying attention to what you do so that you don’t have an accident","slide":104,"shape":"6","bookPage":"87"},{"text":"b drop (v) to decrease; to fall or go down","slide":104,"shape":"7","bookPage":"87"},{"text":"c decide (v) to choose between one possibility and another","slide":104,"shape":"8","bookPage":"87"},{"text":"d shock (n) a big, unpleasant surprise","slide":104,"shape":"9","bookPage":"87"},{"text":"e rise (v) to increase; to go up","slide":104,"shape":"10","bookPage":"87"},{"text":"f precipitation (n) water that falls to the ground as rain or snow","slide":104,"shape":"11","bookPage":"87"},{"text":"1 Where is the Sahara Desert – South Africa or North Africa? North Africa","slide":116,"shape":"12","bookPage":"88"},{"text":"2 Is the weather there hot and dry, or cold and wet? Hot and dry","slide":116,"shape":"14","bookPage":"88"},{"text":"a Stay out of the sun 8","slide":128,"shape":"6","bookPage":"88"},{"text":"b Drink water 6","slide":128,"shape":"7","bookPage":"88"},{"text":"c Stay cool during the day and warm at night 4","slide":128,"shape":"8","bookPage":"88"},{"text":"d Don’t eat too much 7","slide":128,"shape":"9","bookPage":"88"},{"text":"e Stay with your car 5","slide":128,"shape":"10","bookPage":"88"},{"text":"1 The coldest time is d at four o’clock in the morning.","slide":130,"shape":"15","bookPage":"88"},{"text":"2 The average amount of rain in a year c is 70 mm.","slide":130,"shape":"17","bookPage":"88"},{"text":"3 The temperature is 33 °C a between 2 pm and 4 pm.","slide":130,"shape":"6","bookPage":"88"},{"text":"4 The coldest temperature at night b is −1 °C.","slide":131,"shape":"10","bookPage":"88"},{"text":"6 Where might you find an article like this? a in a newspaper b in a travel magazine c in a Maths textbook Answer: b in a travel magazine","slide":143,"shape":"10","bookPage":"88"},{"text":"1 The maximum temperature is 32 °C, in July.","slide":147,"shape":"7","bookPage":"90"},{"text":"2 The minimum temperature is 3 °C, in December.","slide":147,"shape":"8","bookPage":"90"},{"text":"3 In July there are high temperatures.","slide":147,"shape":"9","bookPage":"90"},{"text":"4 In December, there are low temperatures.","slide":147,"shape":"10","bookPage":"90"},{"text":"1 The temperature rises to 32 °C. A","slide":158,"shape":"6","bookPage":"90"},{"text":"2 The temperature drops to 3 °C. B","slide":158,"shape":"7","bookPage":"90"},{"text":"3 The temperature falls to 3 °C. B","slide":158,"shape":"8","bookPage":"90"},{"text":"4 The temperature reaches 32 °C. A","slide":158,"shape":"9","bookPage":"90"},{"text":"1 Use rise(s) and reach(es) to talk about an increase in temperature.","slide":161,"shape":"6","bookPage":"91"},{"text":"2 Use fall(s) and drop(s) to talk about a decrease in temperature.","slide":161,"shape":"7","bookPage":"91"},{"text":"Describe a rainfall graph for your partner to identify.The minimum rainfall is about 60 mm in February. It rises to about 195 mm in July, then falls towards December. This is graph 3.","slide":167,"shape":"11","bookPage":"91"},{"text":"The maximum temperature was twenty degrees.","slide":172,"shape":"6","bookPage":null},{"text":"Rainfall increased in April.","slide":172,"shape":"9","bookPage":null},{"text":"At eight, the temperature was 10°C. By noon, it had risen to 16°C. In the evening, it fell to 12°C.","slide":173,"shape":"6","bookPage":null},{"text":"The warmest day in the practice record was Friday. On that day, the temperature reached 22°C. This was the maximum for the week.","slide":174,"shape":"6","bookPage":null},{"text":"The sky is covered with grey clouds. The maximum temperature is 12°C today.","slide":175,"shape":"7","bookPage":null},{"text":"I think this looks like a cool day. The minimum temperature is 5°C.","slide":176,"shape":"7","bookPage":null},{"text":"1. The head teacher wanted measurements before choosing equipment.\nAnswer: TRUE","slide":181,"shape":"5","bookPage":null},{"text":"11. A building's age does not explain all the temperature differences.\nAnswer: B","slide":181,"shape":"8","bookPage":null},{"text":"1. Summary gap 1\nAnswer: drain","slide":184,"shape":"5","bookPage":null},{"text":"The temperature reached a maximum in July.","slide":193,"shape":"6","bookPage":null},{"text":"The temperature dropped by three degrees.","slide":193,"shape":"9","bookPage":null},{"text":"At dawn, the practice record shows 6°C. Over the next six hours, it rose to 15°C. After reaching that value, it stayed constant until two.","slide":194,"shape":"6","bookPage":null},{"text":"Rainfall rose from 4 mm to 10 mm in the practice data. This was an increase of 6 mm. That increase was the largest daily change shown.","slide":195,"shape":"6","bookPage":null},{"text":"A weather observer is checking equipment outside. Rainfall increased from 4 mm to 8 mm. The observer can record this change.","slide":196,"shape":"7","bookPage":null},{"text":"The observer can compare today’s weather with yesterday’s. The maximum temperature dropped from 18°C to 13°C. This change may explain the cooler air.","slide":197,"shape":"7","bookPage":null},{"text":"1 What do the numbers on the left side of the graph show? Temperatures in degrees Celsius.","slide":202,"shape":"15","bookPage":"92"},{"text":"2 What do the numbers at the bottom of the graph show? Times of day.","slide":202,"shape":"17","bookPage":"92"},{"text":"3 What does the highest point in the graph show? The maximum temperature during the day: 33 °C.","slide":202,"shape":"6","bookPage":"92"},{"text":"4 What does the lowest point in the graph show? The minimum temperature at night: −1 °C.","slide":203,"shape":"10","bookPage":"92"},{"text":"Graphs A and B Precipitation and temperature in Svalbard, Norway over a year.","slide":209,"shape":"13","bookPage":"92"},{"text":"Graphs C and D Precipitation and temperature in Amman, Jordan over a year.","slide":209,"shape":"15","bookPage":"92"},{"text":"1 Graph A shows temperature in degrees Celsius / precipitation in millimetres / the number of hurricanes. Answer: precipitation in millimetres","slide":211,"shape":"15","bookPage":"93"},{"text":"2 Graph B shows temperature in degrees Celsius / average hours of daylight / precipitation in millimetres. Answer: temperature in degrees Celsius","slide":211,"shape":"17","bookPage":"93"},{"text":"3 Graph C shows data for Amman / Svalbard. Answer: Amman","slide":211,"shape":"6","bookPage":"93"},{"text":"4 Graph D shows average temperatures / precipitation. Answer: average temperatures","slide":212,"shape":"15","bookPage":"93"},{"text":"5 Graphs A and C are line graphs / bar charts. Answer: bar charts","slide":212,"shape":"17","bookPage":"93"},{"text":"6 Graphs B and D are line graphs / bar charts. Answer: line graphs","slide":212,"shape":"6","bookPage":"93"},{"text":"Months\nJan\nFeb\nMar\nApr\nMay\nJun\nPrecipitation\n20 mm\n30 mm\n30 mm\n15 mm\n15 mm\n20 mm\nAverage high temperature\n-13 °C\n-13 °C\n-13 °C\n-9 °C\n-3 °C\n3 °C\nAverage low temperature\n-20 °C\n-21 °C\n-20 °C\n-16 °C\n-7 °C\n-1 °C","slide":218,"shape":"14","bookPage":"93"},{"text":"Months\nJul\nAug\nSept\nOct\nNov\nDec\nPrecipitation\n25 mm\n30 mm\n25 mm\n20 mm\n20 mm\n25 mm\nAverage high temperature\n7 °C\n6 °C\n1 °C\n-4 °C\n-8 °C\n-11 °C\nAverage low temperature\n3 °C\n2 °C\n-3 °C\n-9 °C\n-14 °C\n-18 °C","slide":220,"shape":"14","bookPage":"93"},{"text":"Months\nJan\nFeb\nMar\nApr\nMay\nJun\nPrecipitation\n63 mm\n61 mm\n43 mm\n14 mm\n3 mm\n0 mm\nAverage high temperature\n13 °C\n14 °C\n18 °C\n23 °C\n28 °C\n31 °C\nAverage low temperature\n4 °C\n5 °C\n7 °C\n10 °C\n14 °C\n18 °C","slide":224,"shape":"14","bookPage":"93"},{"text":"Months\nJul\nAug\nSept\nOct\nNov\nDec\nPrecipitation\n0 mm\n0 mm\n0 mm\n7 mm\n28 mm\n49 mm\nAverage high temperature\n32 °C\n32 °C\n31 °C\n27 °C\n20 °C\n14 °C\nAverage low temperature\n20 °C\n20 °C\n18 °C\n15 °C\n9 °C\n5 °C","slide":226,"shape":"14","bookPage":"93"},{"text":"1 Which months have the highest temperatures in each place? Svalbard: July. Amman: July and August.","slide":232,"shape":"15","bookPage":"94"},{"text":"2 Which months have the lowest temperatures in each place? Svalbard: February. Amman: January.","slide":232,"shape":"17","bookPage":"94"},{"text":"3 Which months have the most precipitation in each place? Svalbard: February, March and August. Amman: January.","slide":233,"shape":"9","bookPage":"94"},{"text":"4 Which months have the least precipitation in each place? Svalbard: April and May. Amman: June–September.","slide":233,"shape":"11","bookPage":"94"},{"text":"5 What extreme weather do you think these places might have? Svalbard may have heavy snow. Amman may have drought.","slide":234,"shape":"13","bookPage":"94"},{"text":"6 What problems might this cause for the people who live there? Snow may disrupt travel in Svalbard. A shortage of water may make growing food difficult in Amman.","slide":234,"shape":"15","bookPage":"94"},{"text":"adjective\ncomparative\nsuperlative\ncold\ncolder\nthe coldest\nwet\nwetter\nthe wettest\ndry\ndrier\nthe driest\nextreme\nmore / less extreme\nthe most / least extreme","slide":242,"shape":"13","bookPage":"95"},{"text":"adjective\ncomparative\nsuperlative\nlarge\nlarger\nthe largest\nbig\nbigger\nthe biggest\ndangerous\nmore / less dangerous\nthe most / least dangerous\neasy\neasier\nthe easiest","slide":244,"shape":"13","bookPage":"95"},{"text":"1 This is the driest year on record: no rain for two months.","slide":246,"shape":"15","bookPage":"95"},{"text":"2 This winter is colder than last winter.","slide":246,"shape":"17","bookPage":"95"},{"text":"3 Our oceans can have some of the most extreme weather on Earth.","slide":246,"shape":"6","bookPage":"95"},{"text":"4 This summer was wetter than last summer.","slide":247,"shape":"12","bookPage":"95"},{"text":"5 In my country, the biggest problem is the cold weather.","slide":247,"shape":"14","bookPage":"95"},{"text":"1 Cuba has a higher maximum temperature than Iceland. (high)","slide":250,"shape":"6","bookPage":"96"},{"text":"2 Iceland is colder than Cuba. (cold)","slide":250,"shape":"7","bookPage":"96"},{"text":"3 Iceland has the lower temperature of the two countries. (low)","slide":250,"shape":"8","bookPage":"96"},{"text":"4 Cuba is wetter than Iceland. (wet)","slide":250,"shape":"9","bookPage":"96"},{"text":"5 Iceland is drier than Cuba. (dry)","slide":250,"shape":"10","bookPage":"96"},{"text":"6 Cuba is the rainier of the two countries. (rainy)","slide":250,"shape":"11","bookPage":"96"},{"text":"7 Cuba is sunnier than Iceland. (sunny)","slide":250,"shape":"12","bookPage":"96"},{"text":"1 Graph A shows the precipitation in millimetres over one year in Svalbard, Norway.","slide":256,"shape":"6","bookPage":"96"},{"text":"2 Graph B shows the temperature in degrees Celsius over one year in Svalbard, Norway.","slide":256,"shape":"7","bookPage":"96"},{"text":"1 The hottest time is between 2 pm and 4 pm. Temperatures rise to 33 °C. Main idea: The hottest time is between 2 pm and 4 pm. Data: 33 °C.","slide":258,"shape":"12","bookPage":"97"},{"text":"2 The coldest time is at 4 am. Temperatures fall to −1 °C. Main idea: The coldest time is at 4 am. Data: −1 °C.","slide":258,"shape":"14","bookPage":"97"},{"text":"1 The main idea a describes a general feature or trend from the graph.","slide":260,"shape":"12","bookPage":"97"},{"text":"2 The data b is a number from the graph to illustrate the trend.","slide":260,"shape":"14","bookPage":"97"},{"text":"1 New York is as rainy as Houston. c Both cities have an average rainfall of 1,270 millimetres.","slide":263,"shape":"15","bookPage":"97"},{"text":"2 The hottest month is March. b Temperatures reach 37 °C.","slide":263,"shape":"17","bookPage":"97"},{"text":"3 July is sunnier than August. a There are 8.7 hours of sunshine every day in July and 8 hours of sunshine every day in August.","slide":264,"shape":"9","bookPage":"97"},{"text":"4 The coldest month is December. d Temperatures fall to −7 °C.","slide":264,"shape":"11","bookPage":"97"},{"text":"Sentences that belong a The rainiest area in the country is the north-east mountain region, which receives 3,580 millimetres of rain each year. b The Central Valley, where the capital city of San José is located, has the mildest temperature year round. d At the beach, the temperature can rise to as high as 33 °C. f On the highest mountain, called Cerro Chirripó, temperatures can drop to below freezing at night.","slide":267,"shape":"13","bookPage":"97"},{"text":"2 It is too hot to snow in some Latin American cities, such as Managua and Guadalajara.","slide":269,"shape":"14","bookPage":"98"},{"text":"3 There are monsoons in certain parts of the world, for example India and Bangladesh.","slide":269,"shape":"15","bookPage":"98"},{"text":"4 When you go camping, bring important items, such as water and sunscreen.","slide":270,"shape":"14","bookPage":"98"},{"text":"5 You can do a lot of outdoor activities in warm weather, like swimming and walking.","slide":270,"shape":"15","bookPage":"98"},{"text":"6 Some cities are very wet and rainy, for example Hong Kong and Mumbai.","slide":271,"shape":"14","bookPage":"98"},{"text":"The afternoon was the warmest part of the day.","slide":275,"shape":"6","bookPage":null},{"text":"The minimum temperature was lower on Monday.","slide":275,"shape":"9","bookPage":null},{"text":"Place A was warmer than Place B in the practice record. Its afternoon temperature was 22°C, compared with 17°C in B. This difference was greater than the morning gap of two degrees.","slide":276,"shape":"6","bookPage":null},{"text":"Wednesday had the most rain in the practice record. Its total was 20 mm. That amount was twice Tuesday's total of 10 mm.","slide":277,"shape":"6","bookPage":null},{"text":"The snowy village has a lower minimum temperature than the nearby town. Its minimum is −4°C, compared with 2°C in the town. Snow covers the village roofs and path. The person on the path is wearing a thick coat.","slide":278,"shape":"7","bookPage":null},{"text":"Town B has more precipitation than Village A. The town has 12 mm, compared with 3 mm in the village. The difference is 9 mm. These figures compare precipitation, but they do not show which place is warmer.","slide":279,"shape":"7","bookPage":null}];
